(7466831, 1185334, 174908, '<td valign="top">The foreground material detracts from might otherwise been an interesting shot.</td>', 'The foreground material detracts from might otherwise been an interesting shot.', '2016-08-03 01:08:42.000000', NULL, 1),
(7466833, 1185310, 174908, '<td valign="top">The "winged" component is not clear. Yes, cars have wings, but these are not evident in this shot. I also was put off by the framing. The vibrant colours and focus are good.</td>', 'The "winged" component is not clear. Yes, cars have wings, but these are not evident in this shot. I also was put off by the framing. The vibrant colours and focus are good.', '2016-08-03 01:11:14.000000', NULL, 1),
(7466834, 1185055, 174908, '<td valign="top">Good focus, clear image. The central framing, in this case, is a slight negative.</td>', 'Good focus, clear image. The central framing, in this case, is a slight negative.', '2016-08-03 01:12:33.000000', NULL, 1),
(7466835, 1185404, 174908, '<td valign="top">Abstained from voting because I am unsure of the wing connection. But a very nice picture.</td>', 'Abstained from voting because I am unsure of the wing connection. But a very nice picture.', '2016-08-03 01:13:53.000000', NULL, 1),
(7466836, 1185104, 174908, '<td valign="top">The background is distracting, particularly as the colours blend.</td>', 'The background is distracting, particularly as the colours blend.', '2016-08-03 01:14:44.000000', NULL, 1),
(7466838, 1185256, 174908, '<td valign="top">I think it would have been improved if the focus was slightly further back (head and body of the butterfly).</td>', 'I think it would have been improved if the focus was slightly further back (head and body of the butterfly).', '2016-08-03 01:16:17.000000', NULL, 1),
(7466839, 1185387, 174908, '<td valign="top">The debris below the wire detracts from the main element of the image.</td>', 'The debris below the wire detracts from the main element of the image.', '2016-08-03 01:17:25.000000', NULL, 1),
(7466840, 1184996, 174908, '<td valign="top">Framing is off, and the central line pulls the eye away from the subject.</td>', 'Framing is off, and the central line pulls the eye away from the subject.', '2016-08-03 01:18:07.000000', NULL, 1),
(7466842, 1185207, 174908, '<td valign="top">The busy background detracts from the subjects, which are nicely framed against the sky.</td>', 'The busy background detracts from the subjects, which are nicely framed against the sky.', '2016-08-03 01:21:59.000000', NULL, 1),
(7466843, 1185362, 174908, '<td valign="top">Central framing, but choice of focus is good.</td>', 'Central framing, but choice of focus is good.', '2016-08-03 01:23:04.000000', NULL, 1),
(7466844, 1185363, 174908, '<td valign="top">Detail is blown out.</td>', 'Detail is blown out.', '2016-08-03 01:27:50.000000', NULL, 1),
(7466845, 1185154, 174908, '<td valign="top">Framing and background clutter detract from a very clear and contextual shot.</td>', 'Framing and background clutter detract from a very clear and contextual shot.', '2016-08-03 01:28:29.000000', NULL, 1),
(7466846, 1185332, 174908, '<td valign="top">The lamps at the front take the focus and don''t really lead the eye to the key subject (which is nicely in focus).</td>', 'The lamps at the front take the focus and don''t really lead the eye to the key subject (which is nicely in focus).', '2016-08-03 01:29:41.000000', NULL, 1),
(7466899, 1185087, 163081, '<td valign="top">Very well executed light painting. This is a masterpiece. Too bad the butterflies look all similar. (I won''t deduct points for that) So I give you a 10 and my Red dragon award <a href="//www.dpchallenge.com/image.php?IMAGE_ID=1173262" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg"/></a></td>', 'Very well executed light painting. This is a masterpiece. Too bad the butterflies look all similar. (I won''t deduct points for that) So I give you a 10 and my Red dragon award ', '2016-08-03 10:52:10.000000', NULL, 1),
